ary"}, {"id": "61f25cd2-ac19-4b78-af13-e55c76fc8ce4", "type": "concept", "title": "underground economy"}], "description": "Students learn what GDP measures and why it is central to macroeconomic analysis."}, {"id": "8078375c-647a-4df5-b565-4400dbbe4bce", "type": "subtopic", "title": "Expenditure and income approaches", "children": [{"id": "c1b5a0f0-c01a-4801-bc34-068942f4d9a4", "type": "concept", "title": "C + I + G + NX"}, {"id": "e88beaf5-11b8-4735-9a44-39be99455df2", "type": "concept", "title": "consumption"}, {"id": "387a7fbc-5cef-498f-9374-20a19b313fb1", "type": "concept", "title": "investment"}, {"id": "f1d24dd1-7271-4b7a-9ba5-8caaf3c67db3", "type": "concept", "title": "government purchases"}, {"id": "3d35c8b9-97f5-4dc2-a307-7d30e396891c", "type": "concept", "title": "net exports"}, {"id": "548c6de4-d34d-4ced-99f3-245fef0a1085", "type": "concept", "title": "national income"}, {"id": "0b291ace-8894-44c8-8af3-3da7ac9d951e", "type": "concept", "title": "depreciation"}], "description": "This subtopic connects production to spending and income accounting identities."}, {"id": "844d48a7-271b-40a5-96f0-2326d5e07c50", "type": "subtopic", "title": "Real output and GDP limitations", "children": [{"id": "5bf061b7-843d-4d26-9b3a-c0bbb07036cc", "type": "concept", "title": "nominal GDP"}, {"id": "c400e0f2-664e-4e74-b38a-28bec95eb054", "type": "concept", "title": "real GDP"}, {"id": "6d2f602e-fdd7-4a76-911e-eaada739adfd", "type": "concept", "title": "GDP deflator"}, {"id": "5ea36632-0b03-4034-b97b-5b036400471b", "type": "concept", "title": "per capita GDP"}, {"id": "89eb05e1-d120-4dd6-8828-f343f1694712", "type": "concept", "title": "purchasing power parity"}, {"id": "b811a4d8-c613-4cfb-a7c1-0794019f7037", "type": "concept", "title": "home production"}, {"id": "0d35736f-5ea0-492c-bbb8-a1c38f706418", "type": "concept", "title": "well-being"}], "description": "Students interpret GDP carefully and recognize what it misses."}]}, {"id": "da0ca70d-32fb-4a84-84f9-12ce665db38c", "typ