ect"}, {"id": "1d9a9682-9b9e-4fdf-8b7b-95a352916db3", "type": "concept", "title": "exchange-rate effect"}, {"id": "71eca938-5ea5-4a02-b292-175b72214ab5", "type": "concept", "title": "consumer confidence"}, {"id": "5251d5eb-7817-4dce-b93b-1f86dada3364", "type": "concept", "title": "investment demand"}], "description": "Students learn why total spending changes when prices, interest rates, wealth, and expectations change."}, {"id": "b0d9b75c-0877-4426-8fd9-bf2231131e24", "type": "subtopic", "title": "Aggregate supply", "children": [{"id": "22d27212-bb11-4955-94f3-7d9b75fc19a3", "type": "concept", "title": "SRAS"}, {"id": "11e2d025-088d-4a84-8941-b1914f16f0fb", "type": "concept", "title": "LRAS"}, {"id": "15753e9e-e5f6-4c7e-8d6a-0def1fee5851", "type": "concept", "title": "potential output"}, {"id": "1f0d5284-a330-4962-94e7-685d3cf5024d", "type": "concept", "title": "sticky wages"}, {"id": "ec767948-f116-4a96-9e13-ada3a9eed281", "type": "concept", "title": "input costs"}, {"id": "77cdc6c3-bc90-46d5-ace5-30b2d54ff86e", "type": "concept", "title": "supply shock"}, {"id": "d846f0cf-dcea-42a6-b13d-40d24979045c", "type": "concept", "title": "resource prices"}], "description": "This subtopic explains short-run and long-run production capacity."}, {"id": "83e04399-4a72-4fd0-9a0d-211c6b8fd60f", "type": "subtopic", "title": "Macroeconomic equilibrium and shocks", "children": [{"id": "28d98fb1-1628-47cf-bceb-36b360435208", "type": "concept", "title": "output gap"}, {"id": "86349fab-a947-4c16-b1fc-44976ed61f02", "type": "concept", "title": "recessionary gap"}, {"id": "193740e5-a102-4c68-99cc-5c7596d55615", "type": "concept", "title": "inflationary gap"}, {"id": "4385f5de-e283-4b7e-bdd5-952bcebe83d2", "type": "concept", "title": "demand shock"}, {"id": "fe4712cb-1272-4c84-8578-70383775d700", "type": "concept", "title": "supply shock"}, {"id": "ad6cb346-cb70-47c4-a85c-fecebea65c0f", "type": "concept", "title": "stagflation"}], "description": "Students use AD-AS to reason through recessions, inflation, and policy responses."}]}, {"id": "6e92811f-1cc2-457e-ad97-d5048aab9552", "type": "topic", "title": "Consumption, Saving, Investment, and the Loanable Funds Market", "description": "Explain how saving and investment finance capital formation and connect households to long-run growth.", "children": [{"id": "ca81399d-03b1-4a9f-8f0f-4edb573ae6a2", "type": "subtopic", "title": "Consumption and saving behavior", "children": [{"id": "1ac82d4d-6076-495e-bc0e-59f0b06c39c1", "type": "concept", "title": "disposable income"}, {"id": "7ec470d2-6e12-416e-8617-348760766cf9", "type": "concept", "title": "marginal propensity to consume"}, {"id": "8674128b-e180-417c-9580-50863dd30ff6", "type": "concept", "title": "marginal propensity to save"}, {"id": "c33ab2cc-7d04-4d2c-a6f7-7cd31686b3ac", "type": "concept", "title": "wealth effect"}, {"id": "d0250fb0-3f72-4c69-bd9a-5a9a7326b66b", "type": "concept", "title": "consumer expectations"}], "description": "Students learn how households allocate income between current and future spending."}, {"id": "4f2e47fc-f0b5-4b20-85ff-bc214b478f39", "type": "subtopic", "title": "Investment and capital formation", "children": [{"id": "741b48e6-743d-4704-a02a-f81756ba0877", "type": "concept", "title": "physical capital"}, {"id": "67b3fe2c-9f64-46d4-8430-2acd3f04f1d0", "type": "concept", "title": "inventory investment"}, {"id": "6943f234-fc69-447b-86e3-e04181fc4965", "type": "concept", "title": "residential investment"}, {"id": "6c2f85c9-4602-461c-83f4-9c43dc2fe960", "type": "concept", "title": "expected profitability"}, {"id": "0bb4525f-85a0-4dfb-af66-3ccaa1584991", "type": "concept", "title": "user cost of capital"}, {"id": "80eeac00-a0a8-403b-9187-ee869b134e52", "type": "concept", "title": "accelerator effect"}], "description": "This subtopic connects business investment to interest rates and expected returns."}, {"id": "d3a167e2-a05b-43a8-86fa-35e714ac734b", "type": "subtopic", "title": "Loanable funds", "children": [{"id": "b45d