yment"}, {"id": "dccd784e-f8c3-453a-a97a-51120c48540f", "type": "concept", "title": "financial stability"}, {"id": "e0d39157-4acf-45ff-8559-e643087e716f", "type": "concept", "title": "central bank independence"}, {"id": "a11b9617-1b31-4a0b-9f16-216bdafe7c7e", "type": "concept", "title": "credibility"}], "description": "Students learn the policy objectives and institutional responsibilities of central banks."}, {"id": "c7d87906-4bae-46f7-ba39-79ce7922991e", "type": "subtopic", "title": "Policy tools", "children": [{"id": "78ac0e32-49b2-4ef0-9550-4e014e2080a6", "type": "concept", "title": "federal funds rate"}, {"id": "8eca9714-cca4-4b5d-8b7b-ed1e890ff459", "type": "concept", "title": "open market operations"}, {"id": "cb52f68b-9f2a-4dd3-bb1e-3af8eaf5c17b", "type": "concept", "title": "discount rate"}, {"id": "a9e3dec1-f3fb-4a62-a47f-6827f6960e22", "type": "concept", "title": "reserve requirements"}, {"id": "49797c85-ab6b-4a15-9e9f-3555d0b31721", "type": "concept", "title": "interest on reserves"}, {"id": "c3a1bcdc-2635-4c15-8095-3c3f12fc19a9", "type": "concept", "title": "quantitative easing"}, {"id": "b45e6c39-150a-4841-834d-fcc3ec6b1dba", "type": "concept", "title": "forward guidance"}], "description": "This subtopic covers conventional and unconventional monetary-policy instruments."}, {"id": "ad5c5571-c4e9-4c56-806e-e02e2ea417de", "type": "subtopic", "title": "Transmission mechanisms", "children": [{"id": "fdd54b04-a4e4-471e-86d9-86e78c0d595a", "type": "concept", "title": "interest-rate channel"}, {"id": "f1f02d4a-de1d-45db-9f49-00e1abd49d8a", "type": "concept", "title": "credit channel"}, {"id": "73858ce9-c09e-48e9-b303-9290c6fb81d4", "type": "concept", "title": "expectations channel"}, {"id": "8ac5d16f-fd0c-451e-b8da-d0835b899cb3", "type": "concept", "title": "exchange-rate channel"}, {"id": "cd87972b-3f45-4978-a769-330fd436b4fb", "type": "concept", "title": "asset-price channel"}, {"id": "c81a311c-7a46-49ef-989a-a82dd49ef505", "type": "concept", "title": "long