cession"}, {"id": "9d9c5ede-f01a-4f67-a12c-1b8f025d842b", "type": "concept", "title": "trough"}, {"id": "fc32ecf0-5691-401b-9eb7-e2cfe4ce07ad", "type": "concept", "title": "leading indicator"}, {"id": "6341e256-25d2-457d-a245-e1a4617c699e", "type": "concept", "title": "coincident indicator"}, {"id": "52771b46-4c83-4f6c-bd84-2579fdb50b18", "type": "concept", "title": "lagging indicator"}], "description": "Students learn the language of expansions and contractions."}, {"id": "cdcd8d93-5bbd-4e22-be26-d905746d3a2e", "type": "subtopic", "title": "Sources of fluctuations", "children": [{"id": "b244cf83-de8b-4a5d-b00f-4abab0ac0d17", "type": "concept", "title": "aggregate demand shock"}, {"id": "f8cda6ba-5bc9-433f-9a05-5f3053d9015a", "type": "concept", "title": "oil shock"}, {"id": "0755be23-cad6-49ba-b525-a3c49ae54157", "type": "concept", "title": "credit crunch"}, {"id": "f81c2cbd-1e57-4c5e-8805-622ba1760baa", "type": "concept", "title": "housing bubble"}, {"id": "3d78e0c8-6e3e-4fcc-ad91-d91feffdeafe", "type": "concept", "title": "inventory cycle"}, {"id": "9b47fbe7-1dd5-438c-bec5-308cfb10833b", "type": "concept", "title": "expectations shock"}], "description": "This subtopic compares demand, supply, financial, and confidence shocks."}, {"id": "378aa968-a057-44fc-9f7c-11a1d0a210de", "type": "subtopic", "title": "Financial crises and stabilization", "children": [{"id": "766bf740-1349-4625-8cf1-8a8483c11e38", "type": "concept", "title": "systemic risk"}, {"id": "ae2040b3-006d-4b2e-8610-bd3410fa9d31", "type": "concept", "title": "liquidity crisis"}, {"id": "57a4516c-d1db-420f-8f22-7215222b6d62", "type": "concept", "title": "lender of last resort"}, {"id": "2a18796f-1800-4d5b-bf26-d04b0f6a9be1", "type": "concept", "title": "deposit insurance"}, {"id": "7a4611e0-3eb5-463a-9e01-eb6c6767f970", "type": "concept", "title": "macroprudential policy"}, {"id": "c4fbcd9a-1dd8-42ae-8c50-9c424f7b39a6", "type": "concept", "title": "bailout"}, {"id": "0982f2b1-05d6-46f9-b053-f181d2604e43",